// The backend only sends the run id; everything else is read back from
// /assistant-m2m/runs/:runId/context and /tools.
const body = $json.body ?? {};
const runId = typeof body.runId === 'string' ? body.runId.trim() : '';
const valid =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(runId);

return { json: { valid, runId } };

// Runs after "Get context" and "Get tools".
//
// Output:
//   systemPrompt → AI Agent › Options › System Message  ({{ $json.systemPrompt }})
//   userPrompt   → AI Agent › Prompt (Define below)      ({{ $json.userPrompt }})
//   runId        → used by the executar_ferramenta and enviar_mensagem tools
//                  ({{ $('Build prompt').item.json.runId }})
//
// The agent never answers through its final text: every message to the user
// is a call to enviar_mensagem (POST /assistant-m2m/runs/:runId/messages).
// There is no memory node: the backend history (<historico_recente>) already
// holds every message that was really sent.
//
// The system prompt carries instructions, the tool reference of the user's
// plan and the context of the day; everything the user or Jarvis said goes
// to the prompt as data inside tags.

const context = $('Get context').item.json;
const toolset = $('Get tools').item.json;
const runId = $('Config').item.json.runId;

// Angle brackets in user content are neutralised so a message can never
// close or open one of the context tags below (prompt-injection guard).
const escapeTags = (value) =>
  String(value ?? '').replace(/</g, '‹').replace(/>/g, '›');

const messages = [...(context.lastMessages ?? [])];
const ordered = messages.every((message) => message.createdAt)
  ? messages.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))
  : messages.reverse(); // backend sends newest first

const history = ordered
  .filter(
    (message) =>
      !(message.type === 'AI' && /plano atual não inclui|não disponho de busca na web/i.test(String(message.content ?? ''))),
  )
  .map((message) => {
    const author = message.type === 'AI' ? 'jarvis' : 'usuario';
    const kind = message.contentType === 'AUDIO' ? ' tipo="audio"' : '';
    return `<mensagem autor="${author}"${kind}>${escapeTags(message.content)}</mensagem>`;
  })
  .join('\n');

const timezone = context.timezone || 'America/Sao_Paulo';
const fallbackNow = new Date();
const nowIso = context.now || fallbackNow.toISOString();
const nowHuman =
  context.nowHuman ||
  new Intl.DateTimeFormat('pt-BR', {
    timeZone: timezone,
    dateStyle: 'full',
    timeStyle: 'short',
  }).format(fallbackNow);

const rawProfileContext = (context.profileContext || '').trim();
const profileName = (context.profileName || '').trim();
const profileContext =
  [
    profileName && !/^Nome:/im.test(rawProfileContext)
      ? `Nome: ${profileName}`
      : '',
    rawProfileContext,
  ]
    .filter(Boolean)
    .join('\n') || 'Nenhuma informação adicional sobre o usuário.';

const knowledge = (Array.isArray(context.knowledge) ? context.knowledge : []).map(
  ({ id, name, description }) => ({ id, name, description }),
);

// Knowledge bases: RAG search first, whole-base read second. Only rendered
// when the user has at least one base (the tool exists in their plan).
const knowledgeRules = knowledge.length
  ? [
      '# Regra obrigatória das bases de conhecimento (prioridade sobre as demais regras)',
      'O usuário tem bases de conhecimento cadastradas (lista em <bases_de_conhecimento>). Siga estes passos, nesta ordem:',
      '1. SEMPRE, SEMPRE, SEMPRE que alguma informação das bases do usuário puder ser útil para responder ou executar o pedido, por menor que seja a chance, busque PRIMEIRO no RAG: chame executar_ferramenta com tool "database_information", operation "search_knowledge" e data {"query": "<palavras-chave do que procurar>"}. Faça isso antes de responder, de perguntar algo ao usuário ou de dizer que não sabe. Na dúvida, busque. Escreva a query sem pronomes, resolvendo referências pelo histórico ("e o dela?" vira "telefone da Ana").',
      '2. Se a busca no RAG não trouxer o necessário (found false ou trechos que não respondem) e a description de alguma base em <bases_de_conhecimento> indicar que ela pode ser útil ou colaborar com a resposta, leia essa base inteira: executar_ferramenta com tool "database_information", operation "get_database_information" e data {"databaseInformationId": "<id da base>"}. Use também essa leitura quando o pedido exigir a base completa (listar tudo, contar itens, resumir).',
      '3. Responda usando apenas o conteúdo retornado. Só diga que não encontrou depois dos passos 1 e 2.',
      'Não consulte as bases em cumprimentos, agradecimentos ou pedidos que claramente não dependem delas.',
    ].join('\n')
  : '';

const cachedEvents = Array.isArray(context.cachedEvents)
  ? context.cachedEvents
  : [];

const rawDirective = String(context.directive ?? '')
  .replace(
    /- As ferramentas listadas são as que o plano do usuário inclui\.[^\n]*/g,
    '- Apenas quando o usuário pedir uma funcionalidade interna do Jarvis (lembretes, finanças ou base de conhecimento) ausente em "Ferramentas disponíveis", informe que faz parte de outro plano. Para buscas na web (clima, notícias, fatos atuais, eleições, cotações) ou dúvidas gerais, NUNCA diga que o plano não inclui: use a ferramenta browser_search.',
  );

const browserSearchReference = [
  '## Ferramenta direta "browser_search" (incluída em todos os planos): Busca na web em tempo real',
  'Quando usar: Sempre que o usuário pedir informações atuais, clima, notícias, eleições, cotações, fatos recentes ou pedir para pesquisar na web.',
  'Como chamar: Acione diretamente a tool `browser_search` passando o parâmetro `query` (NÃO use `executar_ferramenta` para ela).',
  'Importante: Você TEM acesso à busca na web em todos os planos. Ignore qualquer mensagem antiga em <historico_recente> onde tenha dito que não possui busca na web ou que o plano atual não inclui isso.',
].join('\n');

const sendMessageReference = [
  '## Ferramenta direta "enviar_mensagem" (incluída em todos os planos): Envia uma mensagem de WhatsApp ao usuário',
  'Quando usar: Sempre que for dizer qualquer coisa ao usuário. É o único jeito de ele ler você; o texto final da sua resposta não é entregue.',
  'Como chamar: Acione diretamente a tool `enviar_mensagem` passando o parâmetro `content` com o texto da mensagem (NÃO use `executar_ferramenta` para ela). Uma mensagem por chamada; pode chamar mais de uma vez no mesmo atendimento.',
].join('\n');

const systemPrompt = [
  rawDirective,
  '',
  toolset.reference ?? '',
  '',
  sendMessageReference,
  '',
  browserSearchReference,
  '',
  '# Contexto desta conversa',
  '',
  '<data_e_hora_atual>',
  `${nowHuman} (${nowIso}, fuso ${timezone})`,
  '</data_e_hora_atual>',
  '',
  '<perfil_do_usuario>',
  escapeTags(profileContext),
  '</perfil_do_usuario>',
  '',
  '<eventos_em_cache>',
  escapeTags(JSON.stringify(cachedEvents)),
  '</eventos_em_cache>',
  '',
  ...(knowledgeRules ? [knowledgeRules, ''] : []),
  '<bases_de_conhecimento>',
  escapeTags(JSON.stringify(knowledge)),
  '</bases_de_conhecimento>',
  '',
  '<historico_recente>',
  history || 'Nenhuma mensagem anterior.',
  '</historico_recente>',
].join('\n');

const currentMessage = String(context.currentMessage ?? '');

// AUDIO = automatic transcription of a voice message (see the directive).
const currentMessageTag =
  context.currentMessageType === 'AUDIO'
    ? '<mensagem_atual tipo="audio">'
    : '<mensagem_atual>';

const userPrompt = [
  currentMessageTag,
  escapeTags(currentMessage),
  '</mensagem_atual>',
].join('\n');

return {
  json: {
    runId,
    hasMessage: currentMessage.trim().length > 0,
    systemPrompt,
    userPrompt,
  },
};

parameters.jsonBody:
={{ JSON.stringify({
  tool: $fromAI(
    'tool',
    'Nome exato de uma das ferramentas listadas em "Ferramentas disponíveis" nas instruções.',
    'string'
  ),
  operation: $fromAI(
    'operation',
    'Nome exato de uma das operações dessa ferramenta, conforme a lista dela nas instruções.',
    'string'
  ),
  data: $fromAI(
    'data',
    'Campos da operação como objeto JSON serializado em string. Use "{}" quando não houver campos.',
    'string'
  )
}) }}

={{ JSON.stringify({
  content: $fromAI(
    'content',
    'Texto da mensagem exatamente como o usuário vai ler no WhatsApp: português do Brasil, texto simples, negrito com *um asterisco de cada lado*.',
    'string'
  )
}) }}

={{ JSON.stringify({
  model: 'openai/gpt-oss-120b',
  temperature: 0.2,
  tool_choice: 'required',
  tools: [{ type: 'browser_search' }],
  messages: [
    {
      role: 'system',
      content: 'Busque na web e responda de forma objetiva, precisa e em português do Brasil com os dados encontrados.'
    },
    {
      role: 'user',
      content: $fromAI(
        'query',
        'Pergunta ou termos claros de busca na web (inclua local e data/ano quando relevante, ex.: clima em São Paulo hoje).',
        'string'
      )
    }
  ]
}) }}
